//! The G3 from-source file ladder, derived mechanically from the pinned grammar
//! and syntax-kind-use censuses (bead `fln-vokf`, consumed by `franken_lean-z8j.1.12`).
//!
//! A module `M` in `Init`/`Std` becomes eligible for from-source elaboration once:
//! 1. every direct `Init`/`Std` import of `M` is already eligible (import DAG closure), and
//! 2. every syntax kind `M` uses (from `contracts/REFERENCE_SYNTAX_KIND_USE.txt`) exists in
//!    the available kind set.
//!
//! The checked-in table [`REFERENCE_G3_LADDER`] is generated by
//! `scripts/extract/gen_g3_file_ladder.py` from `contracts/REFERENCE_GRAMMAR_CENSUS.txt` and
//! `contracts/REFERENCE_SYNTAX_KIND_USE.txt`. [`G3Ladder::derive`] reproduces the exact same
//! ordering in Rust so tests can verify zero drift without invoking Python.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt;
use std::sync::OnceLock;

/// The checked-in G3 file ladder, derived from the pinned grammar and kind-use censuses.
pub const REFERENCE_G3_LADDER: &str = include_str!("../../../contracts/REFERENCE_G3_LADDER.txt");

/// The checked-in syntax-kind-use census consumed alongside [`crate::reference_tokens::GRAMMAR_CENSUS`].
pub const SYNTAX_KIND_USE_CENSUS: &str =
    include_str!("../../../contracts/REFERENCE_SYNTAX_KIND_USE.txt");

const LADDER_SCHEMA: &str = "fln-reference-g3-ladder/1";
const GRAMMAR_SCHEMA: &str = "fln-reference-grammar-census/1";
const KIND_USE_SCHEMA: &str = "fln-reference-syntax-kind-use/1";

/// Why a ladder contract or its source censuses could not be parsed or derived.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LadderError {
    Schema {
        expected: &'static str,
        found: Option<String>,
    },
    Malformed {
        line: usize,
        reason: &'static str,
    },
    Duplicate {
        line: usize,
        what: String,
    },
    CountMismatch {
        what: &'static str,
        declared: usize,
        found: usize,
    },
    OpenClosure {
        module: String,
        import: String,
    },
    ImportCycle {
        module: String,
    },
    ModuleSetMismatch,
    NonTopologicalOrder {
        module: String,
        rank: usize,
        import: String,
        import_rank: usize,
    },
    RankGap {
        expected: usize,
        found: usize,
    },
}

impl fmt::Display for LadderError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Schema { expected, found } => {
                write!(f, "expected schema {expected}, found {found:?}")
            }
            Self::Malformed { line, reason } => write!(f, "line {line}: {reason}"),
            Self::Duplicate { line, what } => write!(f, "line {line}: duplicate {what}"),
            Self::CountMismatch {
                what,
                declared,
                found,
            } => write!(f, "count {what} declares {declared}, found {found}"),
            Self::OpenClosure { module, import } => {
                write!(f, "module {module} imports unknown module {import}")
            }
            Self::ImportCycle { module } => {
                write!(f, "import cycle detected involving module {module}")
            }
            Self::ModuleSetMismatch => {
                write!(f, "grammar census and kind-use census module sets differ")
            }
            Self::NonTopologicalOrder {
                module,
                rank,
                import,
                import_rank,
            } => write!(
                f,
                "module {module} (rank {rank}) precedes import {import} (rank {import_rank})"
            ),
            Self::RankGap { expected, found } => {
                write!(f, "expected ladder rank {expected}, found {found}")
            }
        }
    }
}

impl std::error::Error for LadderError {}

/// One ordered module row in the G3 from-source file ladder.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LadderEntry {
    /// 1-based canonical position in the topological ladder.
    pub rank: usize,
    pub module: String,
    pub path: String,
    /// Longest import-chain depth (`0` for root modules with no Init/Std imports).
    pub depth: usize,
    /// Number of syntax kinds introduced for the first time at this rank.
    pub new_kinds_count: usize,
    /// Total distinct syntax kinds used directly by this module.
    pub total_kinds_count: usize,
    /// Size of the cumulative union of syntax kinds through this rank.
    pub cumulative_kinds_count: usize,
    /// Direct Init/Std imports of this module, sorted lexicographically.
    pub imports: Vec<String>,
    /// Syntax kinds introduced for the first time at this rank, sorted lexicographically.
    pub added_kinds: Vec<String>,
}

/// Reachability summary for one syntax kind across the Init/Std DAG.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct KindReach {
    pub kind: String,
    /// Modules whose own parse trees contain this kind.
    pub direct: usize,
    /// Modules whose own parse trees OR transitive imports contain this kind.
    pub transitive: usize,
    /// Earliest ladder rank introducing this kind.
    pub first_rank: usize,
    /// Module at `first_rank`.
    pub first_module: String,
}

/// The complete G3 file ladder plus per-module syntax-kind sets for eligibility queries.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct G3Ladder {
    entries: Vec<LadderEntry>,
    by_module: BTreeMap<String, usize>,
    kind_reach: BTreeMap<String, KindReach>,
    uses_by_module: BTreeMap<String, BTreeSet<String>>,
    max_depth: usize,
}

impl G3Ladder {
    /// Parse and structurally validate a checked-in `REFERENCE_G3_LADDER.txt` contract.
    ///
    /// Note: the checked-in ladder records `added_kinds` per rank rather than repeating each
    /// module's full `uses` set. To query per-module eligibility against arbitrary kind subsets,
    /// pair this with [`Self::attach_kind_uses`] or use [`reference_g3_ladder`].
    pub fn parse(text: &str) -> Result<Self, LadderError> {
        let mut saw_schema = false;
        let mut declared_modules = None;
        let mut declared_kinds = None;
        let mut declared_max_depth = None;
        let mut entries = Vec::new();
        let mut by_module = BTreeMap::new();
        let mut kind_reach = BTreeMap::new();

        for (index, raw) in text.lines().enumerate() {
            let line = index + 1;
            if raw.is_empty() || raw.starts_with('#') {
                continue;
            }
            let fields: Vec<&str> = raw.split('\t').collect();
            if !saw_schema {
                if fields.len() == 2 && fields[0] == "schema" && fields[1] == LADDER_SCHEMA {
                    saw_schema = true;
                    continue;
                }
                return Err(LadderError::Schema {
                    expected: LADDER_SCHEMA,
                    found: Some(raw.to_owned()),
                });
            }
            match fields[0] {
                "reference"
                | "grammar-census-sha256"
                | "kind-use-census-sha256"
                | "generator-sha256" => {}
                "count" => {
                    if fields.len() != 3 {
                        return Err(LadderError::Malformed {
                            line,
                            reason: "count row must have 3 fields",
                        });
                    }
                    let value = fields[2]
                        .parse::<usize>()
                        .map_err(|_| LadderError::Malformed {
                            line,
                            reason: "count value is not a numeral",
                        })?;
                    match fields[1] {
                        "modules" => declared_modules = Some(value),
                        "distinct-kinds" => declared_kinds = Some(value),
                        "max-depth" => declared_max_depth = Some(value),
                        _ => {}
                    }
                }
                "ladder" => {
                    if fields.len() != 10 {
                        return Err(LadderError::Malformed {
                            line,
                            reason: "ladder row must have 10 fields",
                        });
                    }
                    let rank = fields[1]
                        .parse::<usize>()
                        .map_err(|_| LadderError::Malformed {
                            line,
                            reason: "ladder rank is not a numeral",
                        })?;
                    let expected_rank = entries.len() + 1;
                    if rank != expected_rank {
                        return Err(LadderError::RankGap {
                            expected: expected_rank,
                            found: rank,
                        });
                    }
                    let module = fields[2].to_owned();
                    let path = fields[3].to_owned();
                    let depth = parse_kv_usize(fields[4], "depth=", line)?;
                    let new_kinds_count = parse_kv_usize(fields[5], "new-kinds=", line)?;
                    let total_kinds_count = parse_kv_usize(fields[6], "total-kinds=", line)?;
                    let cumulative_kinds_count =
                        parse_kv_usize(fields[7], "cumulative-kinds=", line)?;
                    let imports = parse_kv_list(fields[8], "imports=", line)?;
                    let added_kinds = parse_kv_list(fields[9], "added-kinds=", line)?;
                    if added_kinds.len() != new_kinds_count {
                        return Err(LadderError::CountMismatch {
                            what: "added-kinds",
                            declared: new_kinds_count,
                            found: added_kinds.len(),
                        });
                    }
                    if by_module.insert(module.clone(), entries.len()).is_some() {
                        return Err(LadderError::Duplicate { line, what: module });
                    }
                    entries.push(LadderEntry {
                        rank,
                        module,
                        path,
                        depth,
                        new_kinds_count,
                        total_kinds_count,
                        cumulative_kinds_count,
                        imports,
                        added_kinds,
                    });
                }
                "kind-reach" => {
                    if fields.len() != 6 {
                        return Err(LadderError::Malformed {
                            line,
                            reason: "kind-reach row must have 6 fields",
                        });
                    }
                    let kind = fields[1].to_owned();
                    let direct = parse_kv_usize(fields[2], "direct=", line)?;
                    let transitive = parse_kv_usize(fields[3], "transitive=", line)?;
                    let first_rank = parse_kv_usize(fields[4], "first-rank=", line)?;
                    let first_module = fields[5]
                        .strip_prefix("first-module=")
                        .ok_or(LadderError::Malformed {
                            line,
                            reason: "missing first-module= prefix",
                        })?
                        .to_owned();
                    if kind_reach
                        .insert(
                            kind.clone(),
                            KindReach {
                                kind: kind.clone(),
                                direct,
                                transitive,
                                first_rank,
                                first_module,
                            },
                        )
                        .is_some()
                    {
                        return Err(LadderError::Duplicate { line, what: kind });
                    }
                }
                _ => {
                    return Err(LadderError::Malformed {
                        line,
                        reason: "unknown ladder row tag",
                    });
                }
            }
        }
        if !saw_schema {
            return Err(LadderError::Schema {
                expected: LADDER_SCHEMA,
                found: None,
            });
        }
        let Some(expected_modules) = declared_modules else {
            return Err(LadderError::Malformed {
                line: 1,
                reason: "missing count modules row",
            });
        };
        if expected_modules != entries.len() {
            return Err(LadderError::CountMismatch {
                what: "modules",
                declared: expected_modules,
                found: entries.len(),
            });
        }
        let Some(expected_kinds) = declared_kinds else {
            return Err(LadderError::Malformed {
                line: 1,
                reason: "missing count distinct-kinds row",
            });
        };
        if expected_kinds != kind_reach.len() {
            return Err(LadderError::CountMismatch {
                what: "distinct-kinds",
                declared: expected_kinds,
                found: kind_reach.len(),
            });
        }
        let max_depth = entries.iter().map(|entry| entry.depth).max().unwrap_or(0);
        if let Some(declared) = declared_max_depth
            && declared != max_depth
        {
            return Err(LadderError::CountMismatch {
                what: "max-depth",
                declared,
                found: max_depth,
            });
        }

        // Verify closed topological ordering and cumulative kind monotonicity.
        let mut cumulative = 0usize;
        for entry in &entries {
            for import in &entry.imports {
                let Some(&imp_idx) = by_module.get(import) else {
                    return Err(LadderError::OpenClosure {
                        module: entry.module.clone(),
                        import: import.clone(),
                    });
                };
                let imp_rank = entries[imp_idx].rank;
                if imp_rank >= entry.rank {
                    return Err(LadderError::NonTopologicalOrder {
                        module: entry.module.clone(),
                        rank: entry.rank,
                        import: import.clone(),
                        import_rank: imp_rank,
                    });
                }
            }
            cumulative += entry.added_kinds.len();
            if cumulative != entry.cumulative_kinds_count {
                return Err(LadderError::CountMismatch {
                    what: "cumulative-kinds",
                    declared: entry.cumulative_kinds_count,
                    found: cumulative,
                });
            }
        }
        if cumulative != kind_reach.len() {
            return Err(LadderError::CountMismatch {
                what: "cumulative-vs-kind-reach",
                declared: kind_reach.len(),
                found: cumulative,
            });
        }

        Ok(Self {
            entries,
            by_module,
            kind_reach,
            uses_by_module: BTreeMap::new(),
            max_depth,
        })
    }

    /// Derive the complete G3 file ladder directly from the raw grammar and syntax-kind-use
    /// census texts. This uses the exact same canonical greedy-minimum-new-kinds topological
    /// rule as `scripts/extract/gen_g3_file_ladder.py`.
    pub fn derive(grammar_census: &str, kind_use_census: &str) -> Result<Self, LadderError> {
        let imports = parse_grammar_imports(grammar_census)?;
        let (paths, uses) = parse_kind_uses(kind_use_census)?;
        if imports.len() != paths.len() || imports.keys().ne(paths.keys()) {
            return Err(LadderError::ModuleSetMismatch);
        }

        let depths = compute_depths(&imports)?;
        let max_depth = depths.values().copied().max().unwrap_or(0);

        let mut reverse: BTreeMap<&str, Vec<&str>> =
            imports.keys().map(|m| (m.as_str(), Vec::new())).collect();
        let mut remaining_deps: BTreeMap<&str, usize> = BTreeMap::new();
        for (module, deps) in &imports {
            remaining_deps.insert(module.as_str(), deps.len());
            for dep in deps {
                reverse
                    .get_mut(dep.as_str())
                    .expect("validated closed imports")
                    .push(module.as_str());
            }
        }

        let mut ready: BTreeSet<&str> = remaining_deps
            .iter()
            .filter_map(|(&m, &deg)| (deg == 0).then_some(m))
            .collect();
        let mut cumulative: BTreeSet<String> = BTreeSet::new();
        let mut entries = Vec::with_capacity(imports.len());
        let mut by_module = BTreeMap::new();
        let mut first_seen: BTreeMap<String, (usize, String)> = BTreeMap::new();

        while !ready.is_empty() {
            let chosen = *ready
                .iter()
                .min_by(|&&a, &&b| {
                    let a_uses = &uses[a];
                    let b_uses = &uses[b];
                    let a_new = a_uses.iter().filter(|k| !cumulative.contains(*k)).count();
                    let b_new = b_uses.iter().filter(|k| !cumulative.contains(*k)).count();
                    (a_new, a_uses.len(), depths[a], a).cmp(&(b_new, b_uses.len(), depths[b], b))
                })
                .expect("non-empty ready set");
            ready.remove(chosen);

            let rank = entries.len() + 1;
            let added_kinds: Vec<String> = uses[chosen]
                .iter()
                .filter(|k| !cumulative.contains(*k))
                .cloned()
                .collect();
            for kind in &added_kinds {
                cumulative.insert(kind.clone());
                first_seen.insert(kind.clone(), (rank, chosen.to_owned()));
            }
            by_module.insert(chosen.to_owned(), entries.len());
            entries.push(LadderEntry {
                rank,
                module: chosen.to_owned(),
                path: paths[chosen].clone(),
                depth: depths[chosen],
                new_kinds_count: added_kinds.len(),
                total_kinds_count: uses[chosen].len(),
                cumulative_kinds_count: cumulative.len(),
                imports: imports[chosen].clone(),
                added_kinds,
            });
            for &dependent in &reverse[chosen] {
                let deg = remaining_deps
                    .get_mut(dependent)
                    .expect("dependent in remaining_deps");
                *deg -= 1;
                if *deg == 0 {
                    ready.insert(dependent);
                }
            }
        }

        if entries.len() != imports.len() {
            let stuck = imports
                .keys()
                .find(|m| !by_module.contains_key(*m))
                .cloned()
                .unwrap_or_default();
            return Err(LadderError::ImportCycle { module: stuck });
        }

        // Transitive importer sets per module for kind-reach calculation.
        let mut trans_importers: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
        for module in imports.keys() {
            let mut seen = BTreeSet::from([module.as_str()]);
            let mut stack = vec![module.as_str()];
            while let Some(cur) = stack.pop() {
                for &nxt in &reverse[cur] {
                    if seen.insert(nxt) {
                        stack.push(nxt);
                    }
                }
            }
            trans_importers.insert(module.as_str(), seen);
        }

        let mut direct_users: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
        for (module, ks) in &uses {
            for kind in ks {
                direct_users
                    .entry(kind.as_str())
                    .or_default()
                    .insert(module.as_str());
            }
        }

        let mut kind_reach = BTreeMap::new();
        for kind in &cumulative {
            let direct_set = &direct_users[kind.as_str()];
            let mut transitive_set = BTreeSet::new();
            for &user in direct_set {
                transitive_set.extend(trans_importers[user].iter().copied());
            }
            let (first_rank, first_module) = first_seen[kind].clone();
            kind_reach.insert(
                kind.clone(),
                KindReach {
                    kind: kind.clone(),
                    direct: direct_set.len(),
                    transitive: transitive_set.len(),
                    first_rank,
                    first_module,
                },
            );
        }

        Ok(Self {
            entries,
            by_module,
            kind_reach,
            uses_by_module: uses,
            max_depth,
        })
    }

    pub fn entries(&self) -> &[LadderEntry] {
        &self.entries
    }

    pub fn entry(&self, module: &str) -> Option<&LadderEntry> {
        self.by_module.get(module).map(|&idx| &self.entries[idx])
    }

    pub fn kind_reach(&self) -> &BTreeMap<String, KindReach> {
        &self.kind_reach
    }

    pub fn max_depth(&self) -> usize {
        self.max_depth
    }

    /// Direct syntax kinds used by `module` (populated by [`Self::derive`] and [`reference_g3_ladder`]).
    pub fn module_uses(&self, module: &str) -> Option<&BTreeSet<String>> {
        self.uses_by_module.get(module)
    }

    /// Every module eligible for G3 from-source checking given `available_kinds`:
    /// both its own syntax kinds and every direct/transitive import's syntax kinds
    /// are contained in `available_kinds`. Returned in canonical ladder order.
    pub fn eligible_modules(&self, available_kinds: &BTreeSet<String>) -> Vec<&LadderEntry> {
        let mut eligible = BTreeSet::new();
        let mut out = Vec::new();
        for entry in &self.entries {
            let imports_ok = entry
                .imports
                .iter()
                .all(|dep| eligible.contains(dep.as_str()));
            if !imports_ok {
                continue;
            }
            let Some(uses) = self.uses_by_module.get(&entry.module) else {
                continue;
            };
            if uses.iter().all(|kind| available_kinds.contains(kind)) {
                eligible.insert(entry.module.as_str());
                out.push(entry);
            }
        }
        out
    }

    /// Every syntax kind missing from `available_kinds` across `module` and its reflexive-
    /// transitive import closure. Returns `None` if `module` is not in the ladder.
    pub fn missing_kinds_for(
        &self,
        module: &str,
        available_kinds: &BTreeSet<String>,
    ) -> Option<BTreeSet<String>> {
        if !self.by_module.contains_key(module) {
            return None;
        }
        let mut seen = BTreeSet::from([module]);
        let mut stack = vec![module];
        let mut missing = BTreeSet::new();
        while let Some(cur) = stack.pop() {
            if let Some(uses) = self.uses_by_module.get(cur) {
                for kind in uses {
                    if !available_kinds.contains(kind) {
                        missing.insert(kind.clone());
                    }
                }
            }
            let entry = &self.entries[self.by_module[cur]];
            for imp in &entry.imports {
                if seen.insert(imp.as_str()) {
                    stack.push(imp.as_str());
                }
            }
        }
        Some(missing)
    }

    /// The frontier of ineligible modules whose imports are already eligible, sorted by fewest
    /// missing syntax kinds (then canonical ladder rank).
    pub fn next_unlockable(
        &self,
        available_kinds: &BTreeSet<String>,
        limit: usize,
    ) -> Vec<(&LadderEntry, Vec<String>)> {
        let eligible: BTreeSet<&str> = self
            .eligible_modules(available_kinds)
            .into_iter()
            .map(|entry| entry.module.as_str())
            .collect();
        let mut candidates = Vec::new();
        for entry in &self.entries {
            if eligible.contains(entry.module.as_str()) {
                continue;
            }
            if !entry
                .imports
                .iter()
                .all(|dep| eligible.contains(dep.as_str()))
            {
                continue;
            }
            let Some(uses) = self.uses_by_module.get(&entry.module) else {
                continue;
            };
            let missing: Vec<String> = uses
                .iter()
                .filter(|kind| !available_kinds.contains(*kind))
                .cloned()
                .collect();
            candidates.push((entry, missing));
        }
        candidates.sort_by_key(|(ea, ma)| (ma.len(), ea.rank));
        candidates.truncate(limit);
        candidates
    }
}

/// The checked-in pinned G3 file ladder with per-module syntax-kind uses attached.
pub fn reference_g3_ladder() -> &'static G3Ladder {
    static LADDER: OnceLock<G3Ladder> = OnceLock::new();
    LADDER.get_or_init(|| {
        G3Ladder::derive(
            crate::reference_tokens::GRAMMAR_CENSUS,
            SYNTAX_KIND_USE_CENSUS,
        )
        .expect("invariant: checked-in grammar and kind-use censuses derive a valid G3 ladder")
    })
}

fn parse_kv_usize(field: &str, prefix: &str, line: usize) -> Result<usize, LadderError> {
    field
        .strip_prefix(prefix)
        .ok_or(LadderError::Malformed {
            line,
            reason: "missing expected key= prefix",
        })?
        .parse::<usize>()
        .map_err(|_| LadderError::Malformed {
            line,
            reason: "key= value is not a numeral",
        })
}

fn parse_kv_list(field: &str, prefix: &str, line: usize) -> Result<Vec<String>, LadderError> {
    let raw = field.strip_prefix(prefix).ok_or(LadderError::Malformed {
        line,
        reason: "missing expected list key= prefix",
    })?;
    if raw == "-" || raw.is_empty() {
        return Ok(Vec::new());
    }
    Ok(raw.split(' ').map(str::to_owned).collect())
}

fn parse_grammar_imports(text: &str) -> Result<BTreeMap<String, Vec<String>>, LadderError> {
    let mut saw_schema = false;
    let mut declared_modules = None;
    let mut imports = BTreeMap::new();
    for (index, raw) in text.lines().enumerate() {
        let line = index + 1;
        if raw.is_empty() || raw.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = raw.split('\t').collect();
        if !saw_schema {
            if fields.len() == 2 && fields[0] == "schema" && fields[1] == GRAMMAR_SCHEMA {
                saw_schema = true;
                continue;
            }
            return Err(LadderError::Schema {
                expected: GRAMMAR_SCHEMA,
                found: Some(raw.to_owned()),
            });
        }
        if fields[0] == "count" && fields.len() == 3 && fields[1] == "init-std-modules" {
            declared_modules =
                Some(
                    fields[2]
                        .parse::<usize>()
                        .map_err(|_| LadderError::Malformed {
                            line,
                            reason: "init-std-modules count is not a numeral",
                        })?,
                );
        } else if fields[0] == "module" {
            if fields.len() < 3 {
                return Err(LadderError::Malformed {
                    line,
                    reason: "module row has too few fields",
                });
            }
            let Some(raw_imps) = fields[2].strip_prefix("imports=") else {
                return Err(LadderError::Malformed {
                    line,
                    reason: "module row missing imports=",
                });
            };
            let mut deps: Vec<String> = raw_imps
                .split(' ')
                .filter(|s| !s.is_empty())
                .map(str::to_owned)
                .collect();
            deps.sort();
            deps.dedup();
            if imports.insert(fields[1].to_owned(), deps).is_some() {
                return Err(LadderError::Duplicate {
                    line,
                    what: fields[1].to_owned(),
                });
            }
        }
    }
    if !saw_schema {
        return Err(LadderError::Schema {
            expected: GRAMMAR_SCHEMA,
            found: None,
        });
    }
    let Some(expected) = declared_modules else {
        return Err(LadderError::Malformed {
            line: 1,
            reason: "grammar census missing init-std-modules count",
        });
    };
    if expected != imports.len() {
        return Err(LadderError::CountMismatch {
            what: "init-std-modules",
            declared: expected,
            found: imports.len(),
        });
    }
    for (module, deps) in &imports {
        for dep in deps {
            if !imports.contains_key(dep) {
                return Err(LadderError::OpenClosure {
                    module: module.clone(),
                    import: dep.clone(),
                });
            }
        }
    }
    Ok(imports)
}

type KindUseTables = (BTreeMap<String, String>, BTreeMap<String, BTreeSet<String>>);

fn parse_kind_uses(text: &str) -> Result<KindUseTables, LadderError> {
    let mut saw_schema = false;
    let mut declared_files = None;
    let mut declared_kinds = None;
    let mut paths = BTreeMap::new();
    let mut uses: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();

    for (index, raw) in text.lines().enumerate() {
        let line = index + 1;
        if raw.is_empty() || raw.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = raw.split('\t').collect();
        if !saw_schema {
            if fields.len() == 2 && fields[0] == "schema" && fields[1] == KIND_USE_SCHEMA {
                saw_schema = true;
                continue;
            }
            return Err(LadderError::Schema {
                expected: KIND_USE_SCHEMA,
                found: Some(raw.to_owned()),
            });
        }
        match fields[0] {
            "count" if fields.len() == 3 => {
                let value = fields[2]
                    .parse::<usize>()
                    .map_err(|_| LadderError::Malformed {
                        line,
                        reason: "kind-use count is not a numeral",
                    })?;
                match fields[1] {
                    "files" => declared_files = Some(value),
                    "distinct-kinds" => declared_kinds = Some(value),
                    "errors" | "faults" if value != 0 => {
                        return Err(LadderError::Malformed {
                            line,
                            reason: "kind-use census has non-zero replay errors or faults",
                        });
                    }
                    _ => {}
                }
            }
            "file" => {
                if fields.len() != 6 || fields[4] != "errors=0" {
                    return Err(LadderError::Malformed {
                        line,
                        reason: "malformed or errored file row in kind-use census",
                    });
                }
                if paths
                    .insert(fields[1].to_owned(), fields[2].to_owned())
                    .is_some()
                {
                    return Err(LadderError::Duplicate {
                        line,
                        what: fields[1].to_owned(),
                    });
                }
            }
            "uses" => {
                if fields.len() != 3 {
                    return Err(LadderError::Malformed {
                        line,
                        reason: "malformed uses row in kind-use census",
                    });
                }
                let set: BTreeSet<String> = fields[2]
                    .split(' ')
                    .filter(|s| !s.is_empty())
                    .map(str::to_owned)
                    .collect();
                if uses.insert(fields[1].to_owned(), set).is_some() {
                    return Err(LadderError::Duplicate {
                        line,
                        what: fields[1].to_owned(),
                    });
                }
            }
            _ => {}
        }
    }
    if !saw_schema {
        return Err(LadderError::Schema {
            expected: KIND_USE_SCHEMA,
            found: None,
        });
    }
    let Some(expected_files) = declared_files else {
        return Err(LadderError::Malformed {
            line: 1,
            reason: "kind-use census missing files count",
        });
    };
    if expected_files != paths.len() {
        return Err(LadderError::CountMismatch {
            what: "files",
            declared: expected_files,
            found: paths.len(),
        });
    }
    if paths.len() != uses.len() || paths.keys().ne(uses.keys()) {
        return Err(LadderError::ModuleSetMismatch);
    }
    let distinct: BTreeSet<&str> = uses.values().flatten().map(String::as_str).collect();
    if let Some(expected_kinds) = declared_kinds
        && expected_kinds != distinct.len()
    {
        return Err(LadderError::CountMismatch {
            what: "distinct-kinds",
            declared: expected_kinds,
            found: distinct.len(),
        });
    }
    Ok((paths, uses))
}

fn compute_depths(
    imports: &BTreeMap<String, Vec<String>>,
) -> Result<BTreeMap<&str, usize>, LadderError> {
    fn dfs<'a>(
        module: &'a str,
        imports: &'a BTreeMap<String, Vec<String>>,
        depths: &mut BTreeMap<&'a str, usize>,
        visiting: &mut BTreeSet<&'a str>,
    ) -> Result<usize, LadderError> {
        if let Some(&depth) = depths.get(module) {
            return Ok(depth);
        }
        if !visiting.insert(module) {
            return Err(LadderError::ImportCycle {
                module: module.to_owned(),
            });
        }
        let mut max_dep = None;
        for dep in &imports[module] {
            let d = dfs(dep.as_str(), imports, depths, visiting)?;
            max_dep = Some(max_dep.map_or(d, |cur: usize| cur.max(d)));
        }
        visiting.remove(module);
        let depth = max_dep.map_or(0, |d| d + 1);
        depths.insert(module, depth);
        Ok(depth)
    }

    let mut depths = BTreeMap::new();
    let mut visiting = BTreeSet::new();
    for module in imports.keys() {
        dfs(module.as_str(), imports, &mut depths, &mut visiting)?;
    }
    Ok(depths)
}
